const NL = String.fromCharCode(10);
const raw = $input.first().json;
let scores;
if (Array.isArray(raw)) {
  scores = raw;
} else if (raw && Array.isArray(raw.data)) {
  scores = raw.data;
} else {
  scores = $input.all().map(function (item) {
    const v = item.json;
    if (typeof v === 'number') return v;
    if (v && typeof v.data === 'number') return v.data;
    const vals = Object.values(v || {});
    return typeof vals[0] === 'number' ? vals[0] : 0;
  });
}

const originalChunks = $('Retrieve Candidate Chunks').all().map(i => i.json);

// RBAC: only surface chunks the requester's role is allowed to see. Missing
// visibility (pre-RBAC ingested docs) defaults to 'member' so nothing already
// in the knowledge base silently disappears.
const requesterRole = $('JWT Verify (Chat)').item.json.payload.role;
const allowedVisibilities = requesterRole === 'admin' ? ['member', 'admin'] : ['member'];

const scored = originalChunks.map(function (chunk, idx) {
  return {
    pageContent: chunk.document.pageContent,
    metadata: chunk.document.metadata || {},
    relevanceScore: scores[idx] !== undefined ? scores[idx] : 0
  };
}).filter(function (chunk) {
  const visibility = chunk.metadata.visibility || 'member';
  return allowedVisibilities.indexOf(visibility) !== -1;
});

scored.sort(function (a, b) { return b.relevanceScore - a.relevanceScore; });
const ranked = scored.slice(0, 4);

const topScore = ranked.length > 0 ? ranked[0].relevanceScore : 0;

const contextText = ranked.map((c, i) => {
  const src = c.metadata.source || 'unknown source';
  const section = c.metadata.section || 'n/a';
  const updated = c.metadata.updated_at || 'n/a';
  return '[' + (i + 1) + '] Source: ' + src + ' | Section: ' + section + ' | Last updated: ' + updated + NL + c.pageContent;
}).join(NL + NL);

const citations = ranked.map((c, i) => ({
  marker: '[' + (i + 1) + ']',
  source: c.metadata.source || 'unknown source',
  section: c.metadata.section || 'n/a',
  updatedAt: c.metadata.updated_at || 'n/a',
  relevanceScore: c.relevanceScore
}));

const citationsFormatted = citations.map(c => c.marker + ' ' + c.source + ' (' + c.section + ', updated ' + c.updatedAt + ')').join(NL);

return [{ json: { topScore: topScore, contextText: contextText, citations: citations, citationsFormatted: citationsFormatted, chunkCount: ranked.length } }];

