const response = $input.first().json;
const points = (response.result && response.result.points) || [];

const bySource = {};
for (const point of points) {
  const payload = point.payload || {};
  const meta = payload.metadata || payload;
  const source = meta.source || 'unknown source';
  if (!bySource[source]) {
    bySource[source] = {
      source: source,
      sections: new Set(),
      updatedAt: meta.updated_at || null,
      chunkCount: 0
    };
  }
  const entry = bySource[source];
  entry.chunkCount += 1;
  if (meta.section) entry.sections.add(meta.section);
  if (meta.updated_at && (!entry.updatedAt || meta.updated_at > entry.updatedAt)) {
    entry.updatedAt = meta.updated_at;
  }
}

const documents = Object.values(bySource).map(function (entry) {
  return {
    source: entry.source,
    sectionCount: entry.sections.size,
    chunkCount: entry.chunkCount,
    updatedAt: entry.updatedAt
  };
}).sort(function (a, b) {
  return (b.updatedAt || '').localeCompare(a.updatedAt || '');
});

return [{ json: { documents: documents, count: documents.length } }];

